// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/HelpShots.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Help pages as the app shows them in Settings -> Help: HelpContent
 * (src/panels/HelpModal.tsx) renders a topic's docs page, its heading and
 * line from the page's frontmatter and its MDX through the app's components
 * (docsComponents), framed in the Settings window with the Help topic tree
 * open on the page.
 */
import type { ReactNode } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { SettingsWindow } from "./SettingsWindow";
import { HELP_LABELS, HELP_ORDER, HelpNav, sectionOf, type HelpTopic } from "./HelpNav";

/* docsComponents' markup for the MDX the docs pages use. */
const Kbd = ({ children }: { children: ReactNode }) => <kbd className="kbd">{children}</kbd>;
const Code = ({ children }: { children: ReactNode }) => <code className="doc-code">{children}</code>;
const P = ({ children }: { children: ReactNode }) => <p className="doc-p">{children}</p>;

/** A docs page's frontmatter: the heading and the line under it. */
interface HelpPageMeta {
  title: string;
  description: string;
}

/**
 * HelpContent: one Help page with previous / next links that run through
 * every section. `children` is the page's MDX as Help renders it.
 */
function HelpContent({ topic, page, children }: { topic: HelpTopic; page: HelpPageMeta; children: ReactNode }) {
  const section = sectionOf(topic);
  const index = HELP_ORDER.indexOf(topic);
  const prev = HELP_ORDER[index - 1];
  const next = HELP_ORDER[index + 1];
  const position = section.topics.findIndex((id) => id === topic);
  return (
    <article className="help-article" data-help-topic={topic}>
      <span className="help-crumb">
        {section.label} · {position + 1} of {section.topics.length}
      </span>
      <div className="help-article-head" tabIndex={-1}>
        <div>
          <h3>{page.title}</h3>
          {page.description ? <p className="help-benefit">{page.description}</p> : null}
        </div>
      </div>
      <div className="help-prose">{children}</div>
      <nav className="help-pager" aria-label="Previous and next help pages">
        {prev ? (
          <button type="button" className="help-pager-link" aria-label={`Previous: ${HELP_LABELS[prev]}`}>
            <span className="help-pager-dir">
              <ChevronLeft size={13} aria-hidden="true" />
              Previous
            </span>
            <span className="help-pager-title">{HELP_LABELS[prev]}</span>
          </button>
        ) : (
          <span />
        )}
        {next ? (
          <button type="button" className="help-pager-link is-next" aria-label={`Next: ${HELP_LABELS[next]}`}>
            <span className="help-pager-dir">
              Next
              <ChevronRight size={13} aria-hidden="true" />
            </span>
            <span className="help-pager-title">{HELP_LABELS[next]}</span>
          </button>
        ) : null}
      </nav>
    </article>
  );
}

/**
 * Settings -> Help open on Tips: content/docs/(tips)/tips.mdx as Help renders
 * it. The page's own figure (`<TipsDemo />`, this scene) is left out of the
 * page drawn here, since it would draw itself without end.
 */
export function TipsShot() {
  return (
    <SettingsWindow section="help" helpNav={<HelpNav value="tips" />}>
      <HelpContent topic="tips" page={{ title: "Tips", description: "Small habits that save time every day." }}>
        <P>
          A few habits that save time every day. Everything in these docs is built into the app as well: open <strong>Settings → Help</strong>, or press{" "}
          <Kbd>⇧⌘/</Kbd>.
        </P>
        <P>
          Running several agents on one repository? Turn on <strong>Worktree</strong> in the new-session form so each one gets its own checkout and branch and
          their changes stay apart.
        </P>
        <P>
          Before you reboot a device, press <strong>Save current</strong> in Snapshots. Afterwards, restore the snapshot with{" "}
          <strong>Continue agent conversations</strong> checked so each agent resumes its conversation. A stale session lingering somewhere can go from{" "}
          <strong>Settings → Devices</strong>: expand the device and terminate it.
        </P>
        <P>
          To rename a tile, workspace or snapshot, click its name; <Kbd>Esc</Kbd> cancels. A renamed session is renamed in tmux on its device too, so{" "}
          <Code>tmux ls</Code> there shows the same name.
        </P>
        <P>
          Type a topic into the command palette (<Kbd>⌘K</Kbd>) to jump straight to its Help page. Agents can open any page too, with the{" "}
          <Code>open_help</Code> app command and a page id such as <Code>paste</Code>.
        </P>
      </HelpContent>
    </SettingsWindow>
  );
}
